    catalog[row['product_id']]=product
    catalog[row['ean_code']]=product
rows=list(csv.DictReader(open('/app/dataset/warehouse_dispatches.csv',newline='')))
total=Decimal(0)
for row in rows:
    p=catalog[row['product_id']]
    total += int(row['quantity'])*p['price']
    if row['dispatch_id']=='169':
        print('169 lookup:',p['name'],int(row['quantity'])*p['price'],row['total_weight_kg'],int(row['quantity'])*Decimal(p['unit_weight_kg']))
disposal=[r for r in rows if r['timestamp']=='2023-07-18 03:17:00']
writeoff=sum(int(r['quantity'])*catalog[r['product_id']]['price'] for r in disposal)
print('records',len(rows),'gross',total,'disposal_count',len(disposal),'writeoff',writeoff,'expected',total-writeoff)
print('unknown identifiers', [r for r in rows if r['product_id'] not in catalog])
