from csv import DictReader
from decimal import Decimal
import json


# These eight dispatch lines form the synchronized meat/frozen batch at
# 2023-07-18 03:17, during the severe temperature excursion in both zones.
DISPOSAL_DISPATCH_IDS = {str(dispatch_id) for dispatch_id in range(127, 135)}


def answer() -> int:
    products = {}
    with open('/app/dataset/product_catalog.csv', newline='') as catalog_file:
        for row in DictReader(catalog_file):
            product = {
                'unit_price': Decimal(row['unit_price'].replace(',', '.')),
            }
            # Dispatch 169 is keyed by the kettle EAN rather than product_id.
            products[row['product_id']] = product
            products[row['ean_code']] = product

    revenue = Decimal(0)
    with open('/app/dataset/warehouse_dispatches.csv', newline='') as dispatch_file:
        for row in DictReader(dispatch_file):
            if row['dispatch_id'] in DISPOSAL_DISPATCH_IDS:
                continue
            revenue += int(row['quantity']) * products[row['product_id']]['unit_price']

    return int(revenue)


if __name__ == '__main__':
    with open('/app/answer.json', 'w') as output_file:
        json.dump(answer(), output_file, default=list)
